mapper.update:
UPDATE T_DUEL
   SET GUEST_ID   = #{guestId}
      ,STATUS     = 'ACTIVE'
      ,START_DATE = #{start}
      ,END_DATE   = #{end}
      ,UPD_DAY    = NOW()
 WHERE 1=1
   AND CODE      = #{code}
   AND STATUS    = 'WAITING'
   AND GUEST_ID IS NULL
   AND HOST_ID  <> #{guestId}
   AND INS_DAY   > NOW() - INTERVAL '3 days'

UPDATE T_DUEL
   SET STATUS      = 'DONE'
      ,HOST_SCORE  = #{hostScore}
      ,GUEST_SCORE = #{guestScore}
      ,WINNER_ID   = #{winnerId}
      ,UPD_DAY     = NOW()
 WHERE 1=1
   AND ID     = #{id}
   AND STATUS = 'ACTIVE'
